begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(22);
select ok(not has_table_privilege('authenticated','public.products','SELECT'),'No broad catalog table SELECT');
select ok(not has_table_privilege('authenticated','public.shop_orders','SELECT'),'No broad order SELECT');
select ok(not has_table_privilege('authenticated','public.feedback_messages','SELECT'),'No note table SELECT');
select ok(not has_schema_privilege('authenticated','private','USAGE'),'Private transport schema not exposed');
select ok(not has_function_privilege('authenticated','private.telegram_read(bigint,text)','EXECUTE'),'Direct private read denied');
select ok(not has_function_privilege('anon','private.telegram_redeem(text,bigint,text)','EXECUTE'),'Direct proof redemption denied');
select ok(has_function_privilege('volume_telegram_transport','private.telegram_read(bigint,text)','EXECUTE'),'Only trusted bot transport can read linked projection');
select ok(not has_table_privilege('volume_telegram_transport','auth.sessions','SELECT'),'Bot cannot read Auth sessions');
select ok(not has_table_privilege('volume_core','public.inventory_movements','UPDATE'),'Inventory evidence append only');
select ok(not has_table_privilege('volume_core','public.rank_history','DELETE'),'Rank history retained');
select ok(has_function_privilege('anon','public.shop_catalog(uuid)','EXECUTE'),'Public safe catalog available');
select ok(not has_function_privilege('anon','public.create_shop_order(uuid,jsonb,uuid)','EXECUTE'),'Guest cannot create order');
select ok(not has_function_privilege('authenticated','private.product_can(uuid,text,boolean)','EXECUTE'),'Client cannot invoke authorization helper');
select ok(not has_table_privilege('volume_core','public.rank_history','UPDATE'),'Rank evidence cannot be rewritten');
select ok(not has_table_privilege('volume_telegram_transport','private.telegram_links','SELECT'),'Transport cannot enumerate links');
select ok(not has_schema_privilege('volume_core','auth','USAGE'),'No broad Auth usage for application reader');
select is((select count(*)::int from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private' and c.relname in ('telegram_links','telegram_challenges') and c.relrowsecurity and c.relforcerowsecurity),2,'Private link tables force RLS');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private' and p.proname in ('telegram_read','telegram_redeem') and not ('search_path=""'=any(p.proconfig))),'Trusted transport helpers have fixed empty search path');
select ok(not has_function_privilege('service_role','private.product_can(uuid,text,boolean)','EXECUTE'),'Service role cannot invoke product authorization helper');
select ok(not has_function_privilege('anon','public.save_support(uuid,bigint,text,text)','EXECUTE'),'Guest cannot configure venue support');
select ok(has_function_privilege('authenticated','public.save_support(uuid,bigint,text,text)','EXECUTE'),'Authenticated callers reach scope-enforcing support RPC');
select is((select count(*)::int from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_roles r on r.oid=p.proowner where ((n.nspname='private' and p.proname='product_can') or (n.nspname='public' and p.proname in ('product_access','support_setting','save_support'))) and r.rolname='volume_core' and p.prosecdef and 'search_path=""'=any(p.proconfig)),4,'Replacement helpers retain restricted owner and empty search path');
select * from finish();
rollback;
